-- ----------------------------
-- Table structure for `ledgeraddress`
-- ----------------------------
DROP TABLE IF EXISTS `ledgeraddress`;
CREATE TABLE `ledgeraddress` (
  `Id` bigint(20) NOT NULL AUTO_INCREMENT,
  `LedId` bigint(20) DEFAULT '0',
  `Add1` text,
  `Add2` text,
  `City` text,
  `State` text,
  `StateCode` text,
  `CriUser` int(11) DEFAULT NULL,
  `CriDate` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `PhoneNo` text,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8;

