-- ----------------------------
-- Table structure for `ledgerdetails`
-- ----------------------------
DROP TABLE IF EXISTS `ledgerdetails`;
CREATE TABLE `ledgerdetails` (
  `Id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `EDate` date DEFAULT NULL,
  `Particulars` text,
  `Remarks` text,
  `Dr` decimal(10,2) DEFAULT NULL,
  `Cr` decimal(10,2) DEFAULT NULL,
  `Balance` decimal(10,2) DEFAULT NULL,
  `Mode` varchar(5) DEFAULT NULL,
  `VchNo` varchar(10) DEFAULT NULL,
  `VchType` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;

