-- ----------------------------
-- Table structure for `ledgerentry`
-- ----------------------------
DROP TABLE IF EXISTS `ledgerentry`;
CREATE TABLE `ledgerentry` (
  `Id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `Type` int(10) unsigned DEFAULT '0',
  `EntryNo` varchar(45) DEFAULT '0',
  `EDate` date DEFAULT NULL,
  `DrLid` int(10) unsigned DEFAULT '0',
  `Dr` decimal(10,2) DEFAULT '0.00',
  `CrLid` int(10) unsigned DEFAULT '0',
  `Cr` decimal(10,2) DEFAULT '0.00',
  `RefLid` decimal(10,2) DEFAULT '0.00',
  `Bid` int(10) unsigned DEFAULT '0',
  `Od` int(10) unsigned DEFAULT '0',
  `CriUser` int(10) unsigned DEFAULT '0',
  `CriDate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `Remarks` text,
  `RefId` varchar(45) DEFAULT NULL,
  `Yr` int(11) DEFAULT '1',
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8;

