-- ----------------------------
-- Table structure for `menutbl_copy`
-- ----------------------------
DROP TABLE IF EXISTS `menutbl_copy`;
CREATE TABLE `menutbl_copy` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `Name` text,
  `ParentName` text,
  `IsSubMenu` bit(1) DEFAULT b'0',
  `PId` int(11) DEFAULT NULL,
  `DisplayName` varchar(45) DEFAULT NULL,
  `Whom` text,
  `FrmName` text,
  `Img` longblob,
  `Parameter` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=272 DEFAULT CHARSET=utf8;

