  `Eid` bigint(20) unsigned DEFAULT '0',
  `EDate` date DEFAULT NULL,
  `Pid` int(10) unsigned DEFAULT '0',
  `Qty` decimal(12,3) DEFAULT '0.000',
  `UnitId` int(10) unsigned DEFAULT '0',
  `OriUnitId` int(10) unsigned DEFAULT '0',
  `Barcode` text,
  `PRate` decimal(10,2) DEFAULT '0.00',
  `WRate` decimal(10,2) DEFAULT '0.00',
  `SRate` decimal(10,2) DEFAULT '0.00',
  `Mrp` decimal(10,2) DEFAULT '0.00',
  `TaxId` int(10) unsigned DEFAULT '0',
  `CgstPerc` decimal(10,2) DEFAULT '0.00',
  `CgstAmount` decimal(10,2) DEFAULT '0.00',
  `SgstPerc` decimal(10,2) DEFAULT '0.00',
  `SgstAmount` decimal(10,2) DEFAULT '0.00',
  `IgstPerc` decimal(10,2) DEFAULT '0.00',
  `IgstAmount` decimal(10,2) DEFAULT '0.00',
  `Info1` text,
  `Info2` text,
  `Info3` text,
  `Info4` text,
  `CriUser` int(10) unsigned DEFAULT '0',
  `CriDate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `Amount` decimal(12,2) DEFAULT NULL,
  `DiscPerc` decimal(12,2) DEFAULT '0.00',
  `DiscAmount` decimal(12,2) DEFAULT '0.00',
  `Rate` decimal(12,2) DEFAULT '0.00',
  `Yr` int(11) DEFAULT '1',
  `Cid` int(11) DEFAULT '0',
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

