-- ----------------------------
-- Table structure for `stocktbl`
-- ----------------------------
DROP TABLE IF EXISTS `stocktbl`;
CREATE TABLE `stocktbl` (
  `id` bigint(30) unsigned NOT NULL AUTO_INCREMENT,
  `Pid` int(10) unsigned NOT NULL,
  `InQty` decimal(10,2) DEFAULT '0.00',
  `OutQty` decimal(10,2) DEFAULT '0.00',
  `Eid` varchar(10) DEFAULT '0',
  `Efrm` int(10) unsigned DEFAULT '0',
  `Mode` int(10) unsigned DEFAULT '0',
  `Date` date DEFAULT NULL,
  `PRate` decimal(12,2) DEFAULT '0.00',
  `CriDate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `SRate` decimal(12,2) DEFAULT '0.00',
  `IsActive` tinyint(1) DEFAULT '0',
  `Bid` int(10) unsigned DEFAULT '0',
  `CriUser` int(10) unsigned DEFAULT '0',
  `Mrp` decimal(10,2) DEFAULT '0.00',
  `CRate` decimal(10,2) DEFAULT '0.00',
  `Od` int(11) DEFAULT '0',
  `BinId` int(11) DEFAULT '0',
  `Barcode` varchar(20) DEFAULT NULL,
  `Remarks` text,
  `Yr` int(11) DEFAULT '1',
  `Info1` text,
  `Info2` text,
  `Info3` text,
  `Info4` text,
  `Lid` int(11) DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `Ind_pid` (`Pid`),
