-- ----------------------------
-- View structure for `vw_bankdisplay`
-- ----------------------------
DROP VIEW IF EXISTS `vw_bankdisplay`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_bankdisplay` AS select `a`.`ID` AS `Id`,`a`.`NAME` AS `Name`,`a`.`PRINTNAME` AS `PrintName`,`b`.`Name` AS `Under`,`a`.`INFO1` AS `ADD1`,`a`.`INFO2` AS `ADD2`,`a`.`INFO3` AS `ADD3`,`a`.`INFO4` AS `ADD4`,`a`.`INFO5` AS `ContactNo`,`a`.`INFO6` AS `AccountNo`,`a`.`INFO7` AS `IFSC`,`a`.`INFO8` AS `Notes`,`a`.`OPBALANCE` AS `OpeningBalance`,`a`.`MODE` AS `Mode`,if((`a`.`Active` = 1),'No','Yes') AS `Active` from ((`ledger` `a` join `accgroup` `b`) join `accgroup` `c`) where (((`c`.`Id` = 5) or (`c`.`Id` = 18)) and (`a`.`UNDER_ID` = `b`.`Id`) and (`b`.`Group_Ref` like concat(`c`.`Group_Ref`,'%'))) group by `a`.`ID` ;

