-- ----------------------------
-- Procedure structure for `sp_BrandInsert`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_BrandInsert`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_BrandInsert`(in Id int,in Name text,in UnderName text,in CriUser int)
begin

	declare UnderId int default 0;
	declare UnderCnt int default 0;
	declare out_param int default 0;

    if(UnderName<>'')then
    	set @qry=concat('Select Id,UnderRef into @UnderId,@UnderCnt From Brand where Name=\'',UnderName,'\' limit 1');
  	  PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;
    else
      Set @UnderId=0;
      set @underCnt=0;
  	end if;

  
	if(Id=0 and @UnderId=0)then
			set @qry=concat('Insert into Brand(Name,UnderId,CriUser)Values(\'',Name,'\',\'',0,'\',\'',CriUser,'\')');
			PREPARE s1 FROM @qry;
			EXECUTE s1;
			DEALLOCATE PREPARE s1;

      set @out_param=concat(@UnderCnt,LAST_INSERT_ID());


			set @qry=concat('update Brand Set UnderRef=',@out_param,' where Id=',LAST_INSERT_ID());

			PREPARE s1 FROM @qry;
			EXECUTE s1;
			DEALLOCATE PREPARE s1;
	elseif(Id<>0 and @UnderId=0)then
	
		set @qry=Concat('update Brand Set Name=\'',Name,'\',UnderId=\'',0,'\',CriUser=\'',CriUser,'\' Where Id=',Id);
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
		
		set @out_param=concat(@UnderCnt,Id);
			
		set @qry=concat('update Brand Set UnderRef=',@out_param,' where Id=',Id);
		
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
  elseif(Id=0 and @UnderId<>0)then
			set @qry=concat('Insert into Brand(Name,UnderId,CriUser)Values(\'',Name,'\',\'',@UnderId,'\',\'',CriUser,'\')');

			PREPARE s1 FROM @qry;
			EXECUTE s1;
			DEALLOCATE PREPARE s1;
			
			 set @out_param=concat(@UnderCnt,LAST_INSERT_ID());


			set @qry=concat('update Brand Set UnderRef=',@out_param,' where Id=',LAST_INSERT_ID());

			PREPARE s1 FROM @qry;
			EXECUTE s1;
			DEALLOCATE PREPARE s1;
  elseif(Id<>0 and @UnderId<>0)then
			set @qry=Concat('update Brand Set Name=\'',Name,'\',UnderId=\'',@UnderId,'\',CriUser=\'',CriUser,'\' Where Id=',Id);
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;

		set @out_param=concat(@UnderCnt,Id);

		set @qry=concat('update Brand Set UnderRef=',@out_param,' where Id=',Id);
		
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	end if;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `sp_CateInsert`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_CateInsert`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_CateInsert`(in Id int,in Name text,in UnderName text,in CriUser int)
begin

	declare UnderId int default 0;
	declare UnderCnt int default 0;
	declare out_param int default 0;

    if(UnderName<>'')then
    	set @qry=concat('Select Id,UnderRef into @UnderId,@UnderCnt From Category where Name=\'',UnderName,'\' limit 1');
  	  PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;
    else
      Set @UnderId=0;
      set @underCnt=0;
  	end if;

  Select Id,@UnderId,@underCnt;

	if(Id=0 and @UnderId=0)then
			set @qry=concat('Insert into Category(Name,UnderId,CriUser)Values(\'',Name,'\',\'',0,'\',\'',CriUser,'\')');
			PREPARE s1 FROM @qry;
			EXECUTE s1;
			DEALLOCATE PREPARE s1;

      set @out_param=concat(@UnderCnt,LAST_INSERT_ID());


			set @qry=concat('update Category Set UnderRef=',@out_param,' where Id=',LAST_INSERT_ID());

			PREPARE s1 FROM @qry;
			EXECUTE s1;
			DEALLOCATE PREPARE s1;
	elseif(Id<>0 and @UnderId=0)then
	
		set @qry=Concat('update Category Set Name=\'',Name,'\',UnderId=\'',0,'\',CriUser=\'',CriUser,'\' Where Id=',Id);
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
		
		set @out_param=concat(@UnderCnt,Id);
			
		set @qry=concat('update Category Set UnderRef=',@out_param,' where Id=',Id);
		
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
  elseif(Id=0 and @UnderId<>0)then
set @qry=concat('Insert into Category(Name,UnderId,CriUser)Values(\'',Name,'\',\'',@UnderId,'\',\'',CriUser,'\')');

			PREPARE s1 FROM @qry;
			EXECUTE s1;
			DEALLOCATE PREPARE s1;
			
			 set @out_param=concat(@UnderCnt,LAST_INSERT_ID());


			set @qry=concat('update Category Set UnderRef=',@out_param,' where Id=',LAST_INSERT_ID());

			PREPARE s1 FROM @qry;
			EXECUTE s1;
			DEALLOCATE PREPARE s1;
  elseif(Id<>0 and @UnderId<>0)then
set @qry=Concat('update Category Set Name=\'',Name,'\',UnderId=\'',@UnderId,'\',CriUser=\'',CriUser,'\' Where Id=',Id);
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;

		set @out_param=concat(@UnderCnt,Id);

		set @qry=concat('update Category Set UnderRef=',@out_param,' where Id=',Id);
		
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	end if;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `sp_CbWiseSales`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_CbWiseSales`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_CbWiseSales`(in frmDt Date,in toDt Date)
begin

	Set @qry=concat('select 0 Sno,EDate Dt,B.Name Category,c.Name Brand,sum(d.Amount) TotalAmount 
from Product a,category b,Brand c,saledetails d
where a.Id=d.pid and a.CateId=b.id and a.BrandId=c.id
and d.edate BETWEEN \'',frmDt,'\' and \'',toDt,'\'
group	by EDate,b.id,c.id
');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_ConsolidateProfit`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_ConsolidateProfit`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_ConsolidateProfit`()
begin

	Set @qry=concat('select Year(EDAte)Yr,MonthName(EDate) Mnth,Sum(Qty) TotalQty,round(Qty*prate,2)PRate,round(Qty*srate,2)SRate,round(Qty*srate,2)-round(Qty*prate,2)Profit 
	from saledetails 
group by MOnthName(EDate),Year(EDAte)');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

