		EXECUTE s1;
		DEALLOCATE PREPARE s1;

set @qry=CONCAT('insert into ledgerentry(Type,EntryNo,EDate,DrLid,Dr,Cr,CrLid,criuser,refid,Reflid) 
Select 15,a.eid,a.edate,a.jobac,0,a.EmpAmount,a.ledid,0,0,a.ledid
from jobcardmaster a,jobcarddetails b where a.Eid=b.eid 
union
Select 15,a.eid,a.edate,a.ledid,a.EmpAmount,0,a.jobac,0,0,a.ledid
from jobcardmaster a,jobcarddetails b where a.Eid=b.eid ');
PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;





set autocommit=1;
end
;;
DELIMITER ;

