-- ----------------------------
-- Procedure structure for `sp_correctstock`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_correctstock`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_correctstock`()
begin
	truncate table stocktbl;

	
	insert into stocktbl(pid,inqty,outqty,eid,efrm,date,prate,srate,crate,mrp,barcode,Yr,info1,info2,info3,info4,Lid)
	select pid,qty,0,a.eid,1,a.edate,prate,srate,wrate,mrp,Barcode,0,info1,info2,info3,info4,Sid from purchasedetails a;


insert into stocktbl(pid,inqty,eid,efrm,date,prate,srate,crate,mrp,barcode,Yr,info1,info2,info3,info4)
	select pid,qty,0,0,dt,prate,srate,wrate,mrp,Barcode,Yr,info1,info2,info3,info4 from openstock;
	
	
insert into stocktbl(pid,outqty,eid,efrm,date,srate,lid,PRate,Mrp,cRate,barcode,Yr,info1,info2,info3,info4)
	select pid,qty,a.eid,2,a.edate,rate,cid,PRate,Mrp,WRate,Barcode,0,info1,info2,info3,info4 from saledetails a ;


insert into stocktbl(pid,outqty,eid,efrm,date,srate,lid,PRate,Mrp,cRate,barcode,Yr,info1,info2,info3,info4)
	select pid,qty,a.eid,5,a.edate,rate,SupplierId,PRate,Mrp,WRate,Barcode,0,info1,info2,info3,info4 from purchasereturndetails a,purchasereturnmaster b
where a.eid=b.eid;


insert into stocktbl(pid,inqty,eid,efrm,date,srate,lid,PRate,Mrp,cRate,barcode,Yr,info1,info2,info3,info4)
	select pid,qty,a.eid,6,a.edate,rate,customerId,PRate,Mrp,WRate,Barcode,0,info1,info2,info3,info4 from salesreturndetails a,salesreturnmaster b
where a.eid=b.eid;

  



end
;;
DELIMITER ;

