where a.eid=b.eid;

  
insert into stocktbl(pid,inqty,eid,efrm,date,prate,srate,crate,mrp,barcode)	select pid,qty,0,0,dt,prate,srate,wrate,mrp,Barcode from openstock;

insert into stocktbl(pid,inqty,eid,efrm,date,prate,srate,crate,mrp,barcode)
