call sp_CorrectLedgerEntry();
set @qry=concat('Select 0 Sno,c.name CusName,c.INFO8 AgentName,c.info1 Add1,c.info2 Add2,c.info3 City,c.info4 State,c.info6 GSTNO,Count(a.entryno) BillCnt,
Sum(Dr) TotalAmount,Sum(Cr) Recv,
Sum(Dr)-Sum(Cr) Balance
from ledgerentry a,accgroup b,ledger c 
where c.id=a.crlid and b.id=c.UNDER_ID
and b.name like \'Sundry Debtors (Accounts Receivable)\' and a.edate <=\'',endDt,'\'
GROUP BY c.ID ');
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	
End
;;
