-- ----------------------------
-- Procedure structure for `sp_GetBarCode`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_GetBarCode`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_GetBarCode`()
begin

	declare f varchar(4) default null;
	declare t varchar(1) default null;
	declare s varchar(1) default null;
	declare fi varchar(1) default null;
	declare barcode varchar(7) default null;
	
	set @qry=concat('Select LPAD(Fourth,3,0) into @f from barcode');
	prepare stmt from @qry;
	execute stmt;
	deallocate prepare stmt;

	
	IF(@f=999)then
		update barcode set fourth=1;
		
		set @qry=concat('Select char(ascii(third)+1) into @t from barcode');
		prepare stmt from @qry;
		execute stmt;
		deallocate prepare stmt;

		if(@t='[')THEN
			update barcode set third='A';

			set @qry=concat('Select char(ascii(second)+1) into @s from barcode');
			prepare stmt from @qry;
			execute stmt;
			deallocate prepare stmt;
	
			if(@s='[')THEN
				update barcode set second='A';
				
				set @qry=concat('Select char(ascii(first)+1) into @fi from barcode');
				prepare stmt from @qry;
				execute stmt;
				deallocate prepare stmt;
				
				if(@fi='[')THEN
					update barcode set first='A';
				ELSE
					update barcode set first=char(ascii(first)+1);
				end if;
				
			ELSE
				update barcode set second=char(ascii(second)+1);
			end if;

		ELSE
			update barcode set third=char(ascii(Third)+1);
		end if;
	
	else
		
		update barcode set fourth=fourth+1;
	end if;

	set @qry=concat('Select LPAD(Fourth,3,0),First,Second,Third into @f,@fi,@s,@t from barcode');
		prepare stmt from @qry;
		execute stmt;
		deallocate prepare stmt;
		set @barcode=concat(@fi,@s,@t,@f);

	select @barcode;

end
;;
DELIMITER ;

