-- ----------------------------
-- Procedure structure for `sp_ItemDetails`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_ItemDetails`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ItemDetails`(in Pid int,in frm date,in too date)
begin

	set @qry=concat('(SElect DATE_FORMAT(',frm,',\'%d-%m%Y\')Dt,
    \'OpeningStock \' EntryFrm,\' \' EntryNo,\' \' Name,sum(inqty)-sum(outqty) `IN`,0 `OUT`,0.00 PRate,0.00 SRate  From stocktbl a where 
			a.date<DATE_SUB(\'',frm,'\',INTERVAL 1 day) and a.Pid=',Pid,' )');
			
	set @qry=concat(@qry,' UNION
			(Select DATE_FORMAT(Date,\'%d-%m%Y\')Dt,b.pname `EntryFrm`,Eid EntryNo,
c.name Name,
inqty `IN`,outqty `OUT`,a.prate PRate,a.SRate SRate from stocktbl a,efrm b,ledger c
			where a.Efrm=b.PId and a.pid=',Pid,'  and c.id=a.lid
			and a.date between \'',frm,'\' and \'',too,'\')');
			
	set @qry=concat(@qry,' union (SElect DATE_FORMAT(',too,',\'%d-%m%Y\')Dt,\'ClosingStock \' EntryFrm,\' \' EntryNo,\' \' Name,
    0 `IN`,sum(inqty)-sum(outqty) `OUT`,0.00 PRate,0.00 SRate  From stocktbl a where 
			a.date<=DATE_SUB(\'',too,'\',INTERVAL 1 day) and a.Pid=',Pid,' )');
			

	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

