-- ----------------------------
-- Procedure structure for `sp_ItemMonthly`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_ItemMonthly`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ItemMonthly`(in frm date,in too date)
begin
call sp_correctstock();
	set @qry=concat('select 0 Sno,a.name Name,
	(select Sum(inqty)-sum(outqty) from stocktbl x where x.pid=a.id and x.date<\'',frm,'\' limit 1)OPENING
	,Sum(inQty) INQTY,Sum(OUtQty) OUTQTY,
	(select Sum(inqty)-sum(outqty) from stocktbl x where x.pid=a.id and x.date<=\'',too,'\' limit 1)CLOSING,
	(select round((Sum(inqty)-sum(outqty))*prate) from stocktbl x where x.pid=a.id and x.date<=\'',too,'\' limit 1)STOCKVALUE
	From Product A left outer join stocktbl b on a.id=b.pid
	and 
	b.date between \'',frm,'\' and \'',too,'\' 
	GROUP BY a.id ');
	PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
end
;;
DELIMITER ;

