-- ----------------------------
-- Procedure structure for `sp_LedgerBill`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_LedgerBill`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_LedgerBill`(in frm Date,in Too Date,in Lid int)
begin
		declare unId int default 0;
		call sp_CorrectLedgerEntry;
		set @qry=concat('select Under_id into @unId from ledger where id=',Lid,' ');
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
		
		if(@unId=10)then
				set @qry=concat('Select EntryNo BillNo,EDate Dt,Refid VChNo,if(b.type=3,Abs(Sum(cr)-Sum(Dr)),0)TotalAmount,
						if(b.type=3 and sum(cr)-Sum(dr)<>0,DATEDIFF(CURDATE(),EDate),0)Days,
						if(b.type=6 or b.type=12,Dr,0)Recv,0.00 Balance,remarks,b.Name Frm
						From ledgerentry,Vouchertype b where b.Type=ledgerentry.type and drlid=',Lid,' and edate between\'',frm,'\' and \'',Too,'\' and refid<>0 
GROUP BY ledgerentry.id 
ORDER BY RefId,EDate,EntryNo,b.type');

				PREPARE s1 FROM @qry;
				EXECUTE s1;
				DEALLOCATE PREPARE s1;
		else
			set @qry=concat('Select EntryNo BillNo,EDate Dt,Refid VChNo,if(b.type=1,Abs(Sum(dr)-Sum(cr)),0)TotalAmount,
						if(b.type=1 and sum(dr)-Sum(cr)<>0,DATEDIFF(CURDATE(),EDate),0)Days,
						if(b.type=5 or b.type=11,Cr,0)Paid,0.00 Balance,remarks,b.Name Frm
						From ledgerentry,Vouchertype b where b.Type=ledgerentry.type and drlid=',Lid,' and edate between\'',frm,'\' and \'',Too,'\' and refid<>0 
GROUP BY ledgerentry.id 
ORDER BY RefId,EDate,EntryNo,b.type');

				PREPARE s1 FROM @qry;
				EXECUTE s1;
				DEALLOCATE PREPARE s1;
		end if;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_LedgerDetails`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_LedgerDetails`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_LedgerDetails`(in Lid int,in Bid Int,in FrmDate date,in ToDate Date)
begin

call sp_CorrectLedgerEntry();

truncate ledgerdetails;
	
	set @qry=concat('insert into Ledgerdetails(EDate,Particulars,Remarks,VchType,VchNo,Dr,Cr,Balance,Mode)
		Select \'',FrmDate,'\' EDate,\'Opening Balance\' Particulars,\' \'Remarks,\' \'VchType,\' \' VchNo,0.00 Dr,0.00 Cr,
abs(Sum(Dr)-Sum(Cr)) Balance,
if(sum(Dr)-Sum(Cr)>=0,\' Dr\',\' Cr\') Mode

From ledgerentry a,Ledger b,vouchertype c
where a.CrLid=b.id and a.Type=c.Type and edate <\'',FrmDate,'\' and b.id=',Lid,' and a.bid=',Bid);

		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;



set @qry=concat('insert into Ledgerdetails(EDate,Particulars,Remarks,VchType,VchNo,Dr,Cr,Balance,Mode)
select EDate,d.name Particulars,a.remarks Remarks,c.name VchType,a.entryno VchNo,Dr,Cr,0.0 Balance,\' \' Mode
From ledgerentry a,Ledger b,vouchertype c,ledger d
where a.CrLid=b.id and d.id=a.drlid and a.Type=c.Type and edate between \'',FrmDate,'\' and \'',ToDate,'\' and b.id=',Lid,' and a.bid=',Bid,' Order By a.edate,c.type,a.entryno');

		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
		

set @qry=concat('insert into Ledgerdetails(EDate,Particulars,Remarks,VchType,VchNo,Dr,Cr,Balance,Mode)
Select \'',ToDate,'\' EDate,\'Closing Balance\' Particulars,\' \'Remarks,\' \'VchType,\' \' VchNo,0.00 Dr,0.00 Cr,
abs(Sum(Dr)-Sum(Cr)) Balance,
if(sum(Dr)-Sum(Cr)>=0,\' Dr\',\' Cr\') Mode
From ledgerentry a,Ledger b,vouchertype c
where a.CrLid=b.id and a.Type=c.Type and edate<=DATE_ADD(\'',ToDate,'\',INTERVAL 1 day) and b.id=',Lid,' and a.bid=',Bid);
		
	
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;

Select EDate,Particulars,Remarks,VchType,VchNo,Dr,Cr,Balance,Mode From Ledgerdetails;
		
		
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_LedgerEntryTop10`
