CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_LedgerEntryTop10`(in Lid int)
begin

	set @qry=concat('Select B.Name Type,a.EntryNo EntryNo,a.edate EDate,c.Name Account,Dr,Cr
from ledgerentry A,vouchertype B,ledger c
where a.Type=b.type and Drlid=',Lid,' and c.id=crlid order by a.id desc limit 10;' );
		
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;


end
;;
