DROP PROCEDURE IF EXISTS `Sp_PurchaseDetails`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_PurchaseDetails`(in Eid int)
begin
set @qry=concat('Select 0 Sno,b.id Id,b.Code Code,b.Name Name,b.PrintName PrintName,a.qty Qty,c.id OriUnitId,d.id UnitId,d.name Unit,
e.id TaxId,e.Name TaxName,e.info1 TaxPerc,
a.Barcode Barcode,a.Prate PRate,a.WRate WRate,a.SRate SRate,a.Mrp Mrp,
a.discPerc DiscPerc,a.DiscAmount DiscAmount,
a.Amount,a.CgstPerc CgstPerc,a.CgstAmount CgstAmount,
a.SgstPerc SgstPerc,a.SgstAmount SgstAmount,
a.IgstPerc IgstPerc,a.IgstAmount IgstAmount,
a.oriprate OriPrate,
a.INfo1 `Info1`,
a.info2 `Info2`,a.info3 `Info3`,a.info4 `Info4`
from purchasedetails a,Product b,unit C,unit d,ledger e
where a.Pid=b.id and c.Id=a.OriUnitId and d.id=a.UnitId and e.ID=a.TaxId and a.eid=\'',Eid,'\' ');
