-- ----------------------------
-- Procedure structure for `sp_PurchaseExtraDetails`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_PurchaseExtraDetails`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_PurchaseExtraDetails`(in Eid int)
begin
declare cnt int default 0;

Set @qry=concat('Select count(*) into @cnt from purchaseextradetails  where eid=\'',Eid,'\' ');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;
if(@cnt<>0)then

	Set @qry=concat('Select Parameter Parameter,ParameterValues from purchaseextradetails  where eid=\'',Eid,'\' ');
	PREPARE s1 FROM @qry;
