DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_PurchaseItemDetails`(in FrmDt Date,in TooDt Date)
begin


	set @qry=concat('Select 0 Sno,C.Eid EntryNo,c.EDate Dt,
d.name Vendor,d.INFO6 GSTNO,
C.InvoiceNo InvoiceNo,b.Name Name ,a.Qty Qty,a.OriPrate Prate,(A.oriprate-a.prate)Tax,
a.DiscPerc DiscPerc,a.DiscAmount DiscAmt,Round((A.Qty*A.OriPrate),2) Amt
from purchasedetails a,product b,purchasemaster c,ledger d
where a.Pid=b.id and 
a.eid=c.eid and 
d.ID=c.SupplierId
and A.EDate between \'',FrmDt,'\'  and  \'',TooDt,'\' Order By c.eid ');

	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;

End
;;
DELIMITER ;

