DROP PROCEDURE IF EXISTS `Sp_SaleMasterDisplay`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_SaleMasterDisplay`(in FrmDt Date,in TooDt Date)
begin


	set @qry=concat('Select 0 Sno,C.Eid BillNo,c.EDate Dt,Cus.NAME NAME,Cus.INFO6 GSTNO,b.Name ProductName ,b.Hsn HSN,a.Qty Qty,a.Rate,round((a.Rate*a.Qty),2) Amount,
d.name Tax,a.CgstAmount Cgst,a.SgstAmount Sgst,a.IgstAmount Igst,a.DiscPerc,a.DiscAmount
from ledger d, product b,SaleDetails a,SaleMaster c left outer join ledger Cus on c.CustomerId=cus.ID
where a.Pid=b.id and 
a.eid=c.eid  
and d.ID=a.TaxId
and A.EDate between \'',FrmDt,'\'  and  \'',TooDt,'\'  Order By c.eid ');

	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;

End
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_SaleMasterDisplaydetail`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_SaleMasterDisplaydetail`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_SaleMasterDisplaydetail`(in Frm Date,in too Date)
begin

Set @qry=concat('Select  0 Sno,a.eid BillNo,a.edate Date,b.name Name,d.`Name` Productname,c.Qty,c.Rate,c.Amount
	From salemaster  a,ledger b ,saledetails c,product d
where a.customerid=b.id and c.Eid=a.Eid and c.Pid=d.Id
and a.edate between  \'',Frm,'\' and  \'',too,'\' ');

	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_SaleMasterDisplayGstR`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_SaleMasterDisplayGstR`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_SaleMasterDisplayGstR`(in Frm Date,in too Date)
begin

	Set @qry=concat('Select b.info6 `GSTIN/UIN of Recipient`,a.eid `Invoice Number`,a.edate `Invoice date`,a.TotalAmount `Invoice Value`,

Concat(B.INFo5,\'-\',B.INFO4) `Place Of Supply`,\' N \'`Reverse Charge`,\'Regular \' `Invoice Type`,\' \' `E-Commerce GSTIN`,d.info9 Rate,a.amount `Taxable Value`,
0 `Cess Amount`

	From salemaster  a,ledger b ,saledetails c,Ledger d
where a.customerid=b.id and c.Eid=a.Eid and d.id=c.TaxId
and a.edate between \'',Frm,'\' and  \'',too,'\' GROUP BY A.EID');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_SaleMasterDisplaysuj`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_SaleMasterDisplaysuj`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_SaleMasterDisplaysuj`(in FrmDt Date,in TooDt Date)
begin


	set @qry=concat('Select 0 Sno,C.Eid BillNo,c.EDate Dt,Cus.NAME NAME,a.Info1,a.Info2,a.Info3,a.Info4,b.Name ProductName,a.Qty Qty,Rate,
round((a.Rate*a.Qty)+(a.CgstAmount + a.SgstAmount ),2) Amount,se.Parameter TotAmt,se.ParameterValues ReceivedAmt,se.ParameterValues1 Balance
from ledger d, product b,saleextradetails se,SaleDetails a,SaleMaster c left outer join ledger Cus on c.CustomerId=cus.ID
where a.Pid=b.id and 
a.eid=c.eid
and d.ID=a.TaxId 
and c.Eid=se.Eid
and A.EDate between \'',FrmDt,'\'  and  \'',TooDt,'\'  Order By c.eid ');

	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;

End
;;
DELIMITER ;

