begin

	Set @qry=concat('Select  0 Sno,a.eid BillNo,a.edate Date,b.name Name,
B.INFo5 StateCode,b.INFO9 AgentName,
b.info6 GSTIN,if(a.mode=0,\'CASH\',\'CREDIT\') Mode,
a.amount Amount,a.DiscAmount DiscAmount, AddValue, SubValue, 
Sum(CgstAmount) CGSTAMOUNT,Sum(SgstAmount) SGSTAMOUNT,Sum(IgstAmount) IGSTAMOUNT,
 RoundOff, TotalAmount 
	From salemaster  a,ledger b ,saledetails c
where a.customerid=b.id and c.Eid=a.Eid 
and a.edate between \'',Frm,'\' and  \'',too,'\' GROUP BY A.EID');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
