,DAdd1,DAdd2,DCity,DState,DStateCode,DPhoneNo,SAdd1,SAdd2,SCity,SState,SStateCode,SPhoneNo
	From salemaster  a,ledger b where a.CustomerId=b.id and a.eid=\'',Eid,'\' ');
