-- ----------------------------
-- Procedure structure for `Sp_SalesReturnDetails`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_SalesReturnDetails`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_SalesReturnDetails`(in Eid int)
begin
set @qry=concat('Select 0 Sno,b.id Id,a.Barcode Barcode,b.Code Code,b.Name Name,
(select Sum(inqty)-sum(outqty) from stocktbl where stocktbl.pid=a.pid)Balance,
a.qty Qty,a.Rate,c.id OriUnitId,d.id UnitId,d.name Unit,
e.id TaxId,e.Name TaxName,e.info1 TaxPerc,
a.Prate PRate,a.WRate WRate,a.SRate SRate,a.Mrp Mrp,
a.discPerc DiscPerc,a.DiscAmount DiscAmount,
a.Amount,a.CgstPerc CgstPerc,a.CgstAmount CgstAmount,
a.SgstPerc SgstPerc,a.SgstAmount SgstAmount,
a.IgstPerc IgstPerc,a.IgstAmount IgstAmount,
a.INfo1 `Info1`,
a.info2 `Info2`,a.info3 `Info3`,a.info4 `Info4`,HSN
from SalesReturnDetails a,Product b,unit C,unit d,ledger e
where a.Pid=b.id and c.Id=a.OriUnitId and d.id=a.UnitId and e.ID=a.TaxId and a.eid=\'',Eid,'\' ');
PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;
end
;;
DELIMITER ;

