ELSE
Set @qry=concat('Select Parameter Parameter,ParameterValue ParameterValues from extradetailsmaster  where mode=\'SalesReturn\' ');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;
end if;
end
;;
