begin

set @qry=concat('select a.id Id,a.eid EntryNo,a.edate Dt,e.name EmpName,d.name Machine,c.`Name` Warp,f.name Item,b.Issue Issue,b.Shortage Shortage,a.salary Salary
from ReceiveMaster a,ReceiveDetails b,warp_master c,machine d,empmaster e,item_master f
where a.Eid=b.eid and c.id=b.WarpId and b.MacId=d.id and e.Id=b.EmpId and b.pid=f.id
and a.EDate BETWEEN \'',FrmDt,'\' and \'',ToDt,'\' ');
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	
End
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `sp_StockBal`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_StockBal`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_StockBal`(in dt date,in grpName text,in cateName text)
begin

		
		call sp_correctstock;
		
	set @qry='Select @z:=@z+1 Sno,Code,a.name Name,c.name Brand,d.name Category';
	
	
	set @qry=concat(@qry, ',Sum(inqty-outQty) Qty,if(max(b.prate)=0,a.prate,max(b.prate))PRate,Round(Sum(inqty-outQty)*if(max(b.prate)=0,a.prate,max(b.prate)),2) Amount from Product a,Stocktbl b,Brand c,category d,
(Select @z:=0)v
	where a.id=b.pid and a.brandid=c.id and d.id=a.cateid and
	b.date<=\'',dt,'\'  
	group by pid HAving Qty>=1 order by Sno');
	
	
	
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	

	

	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_StockForSales`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_StockForSales`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_StockForSales`(in valStr text)
begin

	Set @qry=concat('Select a.id Id,Code,a.name Name,a.printname PrintName,ShortName,HSN,
if((Sum(Inqty)-sum(outqty))is null,0,Sum(Inqty)-sum(outqty)) Balance,TaxId,c.name TaxName,c.info1 TaxPerc,
a.unitid UnitId,a.unitid OriUnitId,d.name Unit,
if(b.prate=0 or b.prate is null,a.PRate,b.prate)PRate,
if(b.crate=0 or b.crate is null,a.wrate,b.crate)WRate,
if(b.srate=0 or b.srate is null,a.srate,b.srate)Rate,
if(b.mrp=0 or b.mrp is null,a.mrp,b.mrp)Mrp,
if(b.barcode is null,0,b.barcode) Barcode,b.Info1 Info1,
b.Info2 Info2
From Ledger c,unit d,
Product a LEFT OUTER JOIN stocktbl b on a.id=b.pid
where c.ID=a.taxid and a.unitid=d.id and  a.name like \'',valStr,'%\'
GROUP BY a.id,b.info1,b.mrp');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_StockForSalesByBarCode`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_StockForSalesByBarCode`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_StockForSalesByBarCode`(in valStr text)
begin

	Set @qry=concat('Select a.id Id,Code,a.name Name,a.printname PrintName,ShortName,HSN,
if((Sum(Inqty)-sum(outqty))is null,0,Sum(Inqty)-sum(outqty)) Balance,TaxId,c.name TaxName,c.info1 TaxPerc,
a.unitid UnitId,a.unitid OriUnitId,d.name Unit,
if(b.prate=0 or b.prate is null,a.PRate,b.prate)PRate,
if(b.crate=0 or b.crate is null,a.wrate,b.crate)WRate,
if(b.srate=0 or b.srate is null,a.srate,b.srate)Rate,
if(b.mrp=0 or b.mrp is null,a.mrp,b.mrp)Mrp,
if(b.barcode is null,0,b.barcode) Barcode

From Ledger c,unit d,
Product a LEFT OUTER JOIN stocktbl b on a.id=b.pid
where c.ID=a.taxid and a.unitid=d.id and  b.barCode like \'',valStr,'%\'
GROUP BY a.id,b.mrp');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_StockForSalesByCode`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_StockForSalesByCode`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_StockForSalesByCode`(in valStr text)
begin

	Set @qry=concat('Select a.id Id,Code,b.INfo1,a.name Name,a.printname PrintName,ShortName,HSN,
if((Sum(Inqty)-sum(outqty))is null,0,Sum(Inqty)-sum(outqty)) Balance,TaxId,c.name TaxName,c.info1 TaxPerc,
a.unitid UnitId,a.unitid OriUnitId,d.name Unit,
if(b.prate=0 or b.prate is null,a.PRate,b.prate)PRate,
if(b.crate=0 or b.crate is null,a.wrate,b.crate)WRate,
if(b.srate=0 or b.srate is null,a.srate,b.srate)Rate,
if(b.mrp=0 or b.mrp is null,a.mrp,b.mrp)Mrp,
if(b.barcode is null,0,b.barcode) Barcode

From Ledger c,unit d,
Product a LEFT OUTER JOIN stocktbl b on a.id=b.pid
where c.ID=a.taxid and a.unitid=d.id and  a.Code=\'',valStr,'\'
GROUP BY a.id,b.mrp');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `sp_StockFrmTo`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_StockFrmTo`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_StockFrmTo`(in frm date,in too date)
begin

call sp_correctstock;
set @qry=concat('Select a.Code Code,a.Name Name, 
sum(if(b.Date<\'',frm,'\',InQty-OutQty,0)) OpenStock,
sum(if((Efrm=1 or efrm=0) and b.Date>=\'',frm,'\' and b.date<=\'',too,'\',inQty,0)) Purchase,
sum(if(Efrm=5 and b.Date>=\'',frm,'\' and b.date<=\'',too,'\',outqty,0)) PurchaseReturn,
sum(if(Efrm=2 and b.Date>=\'',frm,'\' and b.date<=\'',too,'\',outqty,0)) Sales,
sum(if(Efrm=6 and b.Date>=\'',frm,'\' and b.date<=\'',too,'\',inqty,0)) SalesReturn,
sum(if(Efrm=10 and b.Date>=\'',frm,'\' and b.date<=\'',too,'\',outqty,0)) Manufacture,
Sum(if(b.date<=\'',too,'\',InQty-OutQty,0)) Closing
From Product a LEFT OUTER JOIN stocktbl b
on a.Id=b.pid 
GROUP BY a.id');

PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

