-- Procedure structure for `Sp_TodayProfit`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_TodayProfit`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_TodayProfit`(in frm Date)
begin

	Set @qry=concat('select Eid `Bill#`,Sum(Qty) TotalQty,round(Qty*prate,2)PRate,round(Qty*srate,2)SRate,round(Qty*srate,2)-round(Qty*prate,2)Profit 
	from saledetails 
	where EDate=\'',frm,'\'
	group by Eid;');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

